function generateUnits(courseId: string, unitCount: number, seed: number): Unit[] {
  const units: Unit[] = [];
  const usedTemplates = new Set<number>();

  for (let u = 0; u < unitCount; u++) {
    let ti: number;
    do {
      ti = (seed + u * 7) % unitTemplates.length;
    } while (usedTemplates.has(ti) && usedTemplates.size < unitTemplates.length);
    usedTemplates.add(ti);
    const template = unitTemplates[ti];

    const unitId = courseId + '-u' + (u + 1);
    const numLessons = 2 + (u % 3);
    const lessonTypes: Lesson['type'][] = ['vocabulary', 'grammar', 'speaking', 'listening'];
    const lessons: Lesson[] = [];

    for (let l = 0; l < numLessons; l++) {
      const lessonId = unitId + '-l' + (l + 1);
      const lt = lessonTypes[l % lessonTypes.length];

      switch (lt) {
        case 'vocabulary':
          lessons.push({
            id: lessonId, type: 'vocabulary',
            title: template.words[0] + '相关词汇',
            completed: false, expReward: 20,
            content: {
              words: template.words.map((w, i) => ({
                id: lessonId + '-w' + (i + 1), term: w, translation: w,
                pronunciation: '/' + w + '/', example: '包含"' + w + '"的例句', exampleTranslation: 'Example with "' + w + '"',
              })),
            },
          } as any);
          break;
        case 'grammar':
          lessons.push({
            id: lessonId, type: 'grammar',
            title: '基本句型结构',
            completed: false, expReward: 25,
            content: {
              rules: [{
                id: lessonId + '-r1', title: template.title + '中的基本句型',
                explanation: '学习' + template.title + '场景中最常用的句型结构。',
                examples: ['关于' + template.words[0] + '的例句A', '关于' + template.words[1] + '的例句B'],
              }],
              exercises: [
                { id: lessonId + '-e1', question: '选择正确的表达方式：', options: ['选项A', '选项B', '选项C'], correctAnswer: '选项A', explanation: '这是最常用的表达方式。' },
                { id: lessonId + '-e2', question: '以下哪个句子是正确的？', options: ['选项A', '选项B', '选项C'], correctAnswer: '选项B', explanation: '注意语法结构的正确性。' },
              ],
            },
          } as any);
          break;
        case 'speaking':
          lessons.push({
            id: lessonId, type: 'speaking',
            title: '口语表达练习',
            completed: false, expReward: 30,
            content: {
              prompt: '请用所学语言表达关于' + template.title + '的内容。',
              targetSentence: '我在学习' + template.title + '。',
              allowedAttempts: 3,
            },
          } as any);
          break;
        case 'listening':
          lessons.push({
            id: lessonId, type: 'listening',
            title: '听力理解训练',
            completed: false, expReward: 25,
            content: {
              audioUrl: '',
              transcript: '这是一段关于' + template.title + '的对话。你会听到两个人讨论' + template.words[0] + '和' + template.words[1] + '。',
              questions: [
                { id: lessonId + '-q1', question: '对话中提到了什么？', options: [template.words[0], template.words[2], template.words[3]], correctAnswer: template.words[0] },
                { id: lessonId + '-q2', question: '这段对话的主题是什么？', options: [template.title, '天气', '购物'], correctAnswer: template.title },
              ],
            },
          } as any);
          break;
      }
    }

    units.push({
      id: unitId, title: template.title, description: template.desc,
      lessons, progress: Math.floor(Math.random() * 80),
    });
  }
  return units;
}

